/// <summary>
/// Extension class of <c>SalesAgreementHeader</c> table
/// </summary>
[ExtensionOf(tableStr(SalesAgreementHeader))]
public final class METSalesAgreementHeader_Extension
{
}

Method.Source:
    public boolean validateWrite()
    {
        boolean ret = next validateWrite();

        ret = this.metValidateAgreementOverlapping() && ret;        

        return ret;
    }

    private boolean metValidateAgreementOverlapping()
    {
        boolean ret = true;
        SalesAgreementHeader agrHeader;

        if(this.CustAccount && this.AgreementState == AgreementState::Effective)
        {
            select firstonly RecId from agrHeader
                where agrHeader.CustAccount == this.CustAccount
                &&      agrHeader.RecId != this.RecId
                &&      agrHeader.AgreementState == this.AgreementState
                &&      (this.DefaultAgreementLineEffectiveDate == dateNull() || agrHeader.DefaultAgreementLineExpirationDate == dateNull() || this.DefaultAgreementLineEffectiveDate <= agrHeader.DefaultAgreementLineExpirationDate)
                &&      (agrHeader.DefaultAgreementLineEffectiveDate == dateNull() || this.DefaultAgreementLineExpirationDate == dateNull() || this.DefaultAgreementLineExpirationDate >= agrHeader.DefaultAgreementLineEffectiveDate);

            if(agrHeader.RecId)
            {
                ret = checkFailed("More than one effective sales agreement is not allowed for the same period.");
            }
        }

        return ret;
    }
